package com.mall.service.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.mall.entity.UserRiskControl; import com.mall.mapper.UserRiskControlMapper; import com.mall.service.RiskControlService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service public class RiskControlServiceImpl implements RiskControlService { private final UserRiskControlMapper mapper; public RiskControlServiceImpl(UserRiskControlMapper mapper){this.mapper=mapper;} public boolean isBlocked(Long userId){return mapper.selectCount(new LambdaQueryWrapper<UserRiskControl>().eq(UserRiskControl::getUserId,userId).eq(UserRiskControl::getStatus,1).and(q->q.isNull(UserRiskControl::getExpireTime).or().gt(UserRiskControl::getExpireTime,LocalDateTime.now())))>0;} @Transactional public void block(Long userId,String type,String reason,Long adminId){var v=new UserRiskControl();v.setUserId(userId);v.setRiskType(type==null?"BLACKLIST":type);v.setReason(reason);v.setStatus(1);v.setCreatedBy(adminId);v.setCreateTime(LocalDateTime.now());v.setUpdateTime(LocalDateTime.now());mapper.insert(v);} @Transactional public void unblock(Long userId,String type){mapper.update(null,new com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<UserRiskControl>().eq(UserRiskControl::getUserId,userId).eq(type!=null,UserRiskControl::getRiskType,type).set(UserRiskControl::getStatus,0).set(UserRiskControl::getUpdateTime,LocalDateTime.now()));} }
